<?php

namespace Database\Seeders;

use Illuminate\Support\Facades\File;

class LandingImageSaver
{
    public static function extractImages(): void
    {
        $dir = public_path('images/landing/templates');
        if (! File::isDirectory($dir)) {
            File::makeDirectory($dir, 0755, true);
        }

        // Hero Background
        $heroBase64 = '';
        File::put(public_path('images/landing/hero-bg.jpg'), base64_decode($heroBase64));

        // CTA Background
        $ctaBase64 = '';
        File::put(public_path('images/landing/cta-bg.jpg'), base64_decode($ctaBase64));

        // Product template previews
        $templates = [
            'neraya' => '',
            'lumina' => '',
            'sakura' => '',
            'velora' => '',
            'madani' => '',
            'aluna' => '',
            'flore' => '',
            'savana' => '',
        ];

        foreach ($templates as $slug => $b64) {
            $dest = public_path("images/landing/templates/{$slug}.jpg");
            if (! File::exists($dest)) {
                File::put($dest, base64_decode($b64));
            }
        }
    }
}
